namespace ghidra.app.plugin.core.datamgr.tree;




using docking;
using ghidra.app.plugin.core.datamgr;
using ghidra.program.model.data;

public class DataTypeTableContext : DefaultActionContext, DataTypeContext {

	private List<DataType> selectedTypes;

	DataTypeTableContext(DataTypesTableProvider provider, List<DataType> selectedTypes) : base(provider, provider.getTable())
    {
		this.selectedTypes = selectedTypes;
	}

	/* @Override */
	public DataType getSelectedDataType() {
		if (selectedTypes.size() == 1) {
			return selectedTypes.get(0);
		}
		return null;
	}

	/* @Override */
	public List<DataType> getSelectedDataTypes() {
		return Collections.unmodifiableList(selectedTypes);
	}

	/* @Override */
	public bool hasSelectedDataTypes() {
		return !selectedTypes.isEmpty();
	}
}
